// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CheckIcon, ChevronDownIcon } from 'lucide-react'

import { Btn, Code, DemoStage, PanelChrome, type Build } from '@/app/demos/stage'
import { cn } from '@/shared/utils/cn'

import { CAPTIONS, FORMATTED, MINIFIED, TYPES } from './script'

const TREE: { key: string; value?: string; tone?: string; depth: number; d?: string }[] = [
  { key: 'root', value: '{2}', depth: 0 },
  { key: 'user', value: '{3}', depth: 1 },
  { key: 'id', value: '42', tone: 'text-amber', depth: 2 },
  { key: 'name', value: '"Ada"', tone: 'text-emerald', depth: 2 },
  { key: 'roles', value: '[2]', depth: 2, d: 'roles-toggle' },
  { key: '0', value: '"admin"', tone: 'text-emerald', depth: 3, d: 'roles-child' },
  { key: '1', value: '"dev"', tone: 'text-emerald', depth: 3, d: 'roles-child' },
  { key: 'active', value: 'true', tone: 'text-rose', depth: 1 },
]

const build: Build = ({ tl, q, qa, step, final, move, click, type, wait, cursorOut }) => {
  step(0)
  move('input', { at: 0.3, ax: 0.2 })
  click('input')
  tl.set(q('ph'), { opacity: 0 })
  type('input-text', MINIFIED, { speed: 0.014 })

  step(1, '+=0.5')
  move('btn-format')
  click('btn-format')
  tl.to(q('input'), { opacity: 0, y: -18, scale: 0.94, duration: 0.45 }, '<0.1')
  tl.set(q('fmt'), { opacity: 1 }, '<0.2')
  tl.fromTo(
    qa('fmt-line'),
    { opacity: 0, z: -260, rotateX: -60, y: 24 },
    { opacity: 1, z: 0, rotateX: 0, y: 0, stagger: 0.06, duration: 0.9 },
    '<0.2',
  )
  tl.to(q('valid'), { opacity: 1, scale: 1, duration: 0.5, ease: 'back.out(2.4)' }, '-=0.4')
  wait(0.9)

  step(2)
  move('tab-tree')
  click('tab-tree')
  tl.to(
    q('tab-tree'),
    { color: '#f4f4f6', backgroundColor: 'rgba(255,255,255,0.1)', duration: 0.2 },
    '<',
  )
  tl.to(q('tab-format'), { color: '#8b8b9a', backgroundColor: 'transparent', duration: 0.2 }, '<')
  tl.to(q('fmt'), { opacity: 0, x: -40, duration: 0.4 }, '<0.1')
  tl.set(q('tree'), { opacity: 1 }, '<0.2')
  tl.fromTo(
    qa('node'),
    { opacity: 0, x: 30 },
    { opacity: 1, x: 0, stagger: 0.05, duration: 0.6 },
    '<0.2',
  )
  tl.to(q('tree'), { rotateY: -16, rotateX: 10, duration: 1.1, ease: 'power2.inOut' })
  tl.to(qa('depth-2'), { z: 40, duration: 1.1, ease: 'power2.inOut' }, '<')
  tl.to(qa('depth-3'), { z: 80, duration: 1.1, ease: 'power2.inOut' }, '<')
  move('roles-toggle', { ax: 0.1 })
  click('roles-toggle')
  tl.to(
    qa('roles-child'),
    {
      height: 0,
      opacity: 0,
      paddingTop: 0,
      paddingBottom: 0,
      duration: 0.45,
      stagger: 0.05,
      ease: 'power3.inOut',
    },
    '<',
  )
  tl.to(q('roles-chevron'), { rotate: -90, duration: 0.3 }, '<')
  tl.to(q('tree'), { rotateY: 0, rotateX: 0, duration: 0.8, ease: 'power2.inOut' }, '+=0.3')
  tl.to([...qa('depth-2'), ...qa('depth-3')], { z: 0, duration: 0.8, ease: 'power2.inOut' }, '<')

  step(3, '+=0.2')
  move('btn-ts')
  click('btn-ts')
  tl.to(q('tree'), { opacity: 0, scale: 0.9, filter: 'blur(6px)', duration: 0.45 }, '<0.1')
  tl.set(q('ts'), { opacity: 1 }, '<0.25')
  tl.fromTo(
    qa('ts-line'),
    { opacity: 0, x: -14, filter: 'blur(4px)' },
    { opacity: 1, x: 0, filter: 'blur(0px)', stagger: 0.05, duration: 0.5 },
    '<0.25',
  )
  cursorOut('+=0.2')
  final()
  wait(2)
  tl.to(q('body'), { opacity: 0, duration: 0.5 })
}

export default function Demo() {
  return (
    <DemoStage
      label="JSON Toolkit formatting a minified payload, folding it as a tree and converting it to TypeScript"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome
        aside={
          <span
            data-d="valid"
            className="flex scale-75 items-center gap-1 rounded-full bg-emerald/15 px-2 py-0.5 text-[10px] text-emerald opacity-0"
          >
            <CheckIcon className="size-3" /> Valid · 7 keys
          </span>
        }
      >
        <div data-d="body" className="flex h-full flex-col">
          <div className="flex gap-1 rounded-full border border-line bg-canvas/70 p-1 text-[11px]">
            <span data-d="tab-format" className="rounded-full bg-white/10 px-3 py-1 text-ink">
              Format
            </span>
            <span data-d="tab-tree" className="rounded-full px-3 py-1 text-muted">
              Tree
            </span>
            <span className="rounded-full px-3 py-1 text-muted">JSONPath</span>
            <span className="rounded-full px-3 py-1 text-muted">Convert</span>
          </div>
          <div className="relative mt-3 flex-1 [perspective:900px]">
            <div
              data-d="input"
              className="absolute inset-x-0 top-0 h-24 rounded-xl border border-line bg-canvas/80 p-3 font-mono text-[11px] leading-relaxed"
            >
              <span data-d="ph" className="absolute left-3 top-3 text-muted">
                Paste JSON…
              </span>
              <span data-d="input-text" className="demo-caret break-all text-ink-soft" />
            </div>
            <div
              data-d="fmt"
              className="absolute inset-x-0 top-0 opacity-0 [transform-style:preserve-3d]"
            >
              <Code code={FORMATTED} name="fmt" />
            </div>
            <div
              data-d="tree"
              className="absolute inset-x-0 top-0 rounded-xl border border-line bg-canvas/80 p-2 font-mono text-[11.5px] opacity-0 [transform-style:preserve-3d]"
            >
              {TREE.map((node) => (
                <div
                  key={node.key + node.depth}
                  data-d={cn('node', `depth-${node.depth}`, node.d)}
                  className="flex items-center gap-1.5 overflow-hidden rounded-md px-1.5 py-[3px] opacity-0"
                  style={{ paddingLeft: 6 + node.depth * 16 }}
                >
                  {node.value?.startsWith('{') || node.value?.startsWith('[') ? (
                    <ChevronDownIcon
                      data-d={node.d === 'roles-toggle' ? 'roles-chevron' : undefined}
                      className="size-3 text-muted"
                    />
                  ) : (
                    <span className="w-3" />
                  )}
                  <span className="text-[var(--accent)]">{node.key}</span>
                  <span className="text-muted">:</span>
                  <span className={node.tone ?? 'text-muted'}>{node.value}</span>
                </div>
              ))}
            </div>
            <div data-d="ts" className="absolute inset-x-0 top-0 opacity-0">
              <Code code={TYPES} name="ts" />
            </div>
          </div>
          <div className="mt-3 flex gap-2">
            <Btn d="btn-format" primary>
              Format
            </Btn>
            <Btn>Minify</Btn>
            <Btn d="btn-ts" className="ml-auto">
              → TypeScript
            </Btn>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
